#include "stdafx.h"#include "H_Class.h"static SBlockCreate LT( "LT", SH_LT::Create );#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_LT,W_LT,11)void SH_LT::InitParm(){#include "Blocks/LT.h"   s_defFlag = SVarInfo::efParam;#include "Blocks/LT_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}class LT_IMPL : public W_LT{public:  void StepT( SStepCalcParams &dt );};void SH_LT::StepT( SStepCalcParams &dt ){  InputConnectionsTransfer();  LT_IMPL *impl = reinterpret_cast<LT_IMPL*>(W);  impl->StepT( dt );  OutputConnectionsTransfer();}//////////////////////////////////////////////////////////////////////////void LT_IMPL::StepT( SStepCalcParams &dt ){  double V1 = IN[1];  double V2 = (1==NUMOFINPUTS) ? TP : IN[2];  if( IsNaN(V1) )  {    OUT = INBADOPT;    return;  }  if( 2==NUMOFINPUTS && IsNaN(V2) )  {    OUT = INBADOPT;    return;  }  if( V1 < V2 )    OUT = 1;  else if ( V1 >= (V2 + DEADBAND) )    OUT = 0;}